(\lambda y.e)[x:=d]=
\begin{cases}
\lambda y.e,&y=x,\\
\lambda y.e[x:=d],&y\ne x\land y\notin\operatorname{UFV}(d),\\
\lambda z.(e[y:=z])[x:=d],&y\ne x\land y\in\operatorname{UFV}(d),
\end{cases}

(\Lambda y.t)[x:=s]=
\begin{cases}
\Lambda y.t,&y=x,\\
\Lambda y.t[x:=s],&y\ne x,\ y\notin\operatorname{FV}(s),\\
\Lambda z.(t[y:=z])[x:=s],&y\ne x,\ y\in\operatorname{FV}(s),
\end{cases}

\mathsf{Rule}_{PiI}^{CDLE}
=\{(\langle\Gamma,x:A\vdash t:B\rangle,\Gamma\vdash\lambda x.t:\Pi x:A.B)\},
\quad
\mathsf{Rule}_{PiE}^{CDLE}
=\{(\langle\Gamma\vdash f:\Pi x:A.B,\Gamma\vdash a:A\rangle,\Gamma\vdash f\,a:B[x:=a])\},

\mathsf{Rule}_{Proj_1}^{CDLE}
=\{(\langle\Gamma\vdash p:\iota x:A.B\rangle,\Gamma\vdash p.1:A)\},
\quad
\mathsf{Rule}_{Proj_2}^{CDLE}
=\{(\langle\Gamma\vdash p:\iota x:A.B\rangle,\Gamma\vdash p.2:B[x:=p.1])\},
